"""The zombie pose clearance to the FURNITURE, precomputed per stance and pedestal height for the quick search (R4, decisions-log M142; navigation proposal 12.7).

    hcm = HomeClearanceMap(model, data, chk)                    # once per scene: the furniture's distance field and the arms' surface points
    ok = hcm.clear_mask(heading, qs, X, Y)                      # (nq, ny, nx) bool: the arms at home are clear of the furniture at every cell and pedestal command
    robot = {**robot_geometry(model), "home_clear": hcm.clear_mask}   # the quick search (src/stance_finder.find_stances) then blocks the cells that are not clear

The arms at the zombie pose are rigid relative to the torso, which rides up with the pedestal; so for any stance (x, y, heading, q) their surface points are known and the furniture's signed distance
field (a grid made once from the scene's static collision geoms: boxes, cylinders, capsules, spheres) gives their clearance by a lookup. This replaces the slow per-stance geometry queries of
`StanceChecks.home_clearance` (about 0.03 s each) for the whole floor window. "Furniture" is every static collision geom of the scene except the objects on the table (the beaker, the hotplate and
the slots of src/full_check.py): those are checked live in the full check (R2i).

The result is an ESTIMATE of the exact clearance (surface samples about 1.5 cm apart and a trilinear field of 2 cm voxels): it is made slightly lenient (`slack`, 1 cm: a cell counts as clear
down to `min_clearance - slack`), because the full check measures the exact value and decides; the test experiments/full_check_test.py compares it with the exact function.

Contents:
    furniture_primitives, SdfGrid, surface_samples, HomeClearanceMap.
"""

import math

import mujoco
import numpy as np
from scipy import ndimage

from src import robot_specs
from src.task_config import STANCE_CFG, STANCE_REQUIREMENTS

T = mujoco.mjtGeom


def furniture_primitives(model, data, exclude_bodies=("task_beaker", "task_hotplate"), exclude_geom_prefix="fc_slot", robot_root="base_link"):
    """Lists the static collision geoms of the scene that are furniture: (type, centre, rotation, size).

    Args:
        model (mujoco.MjModel): The compiled model.
        data (mujoco.MjData): Its data after a kinematics pass (the geoms' world poses).
        exclude_bodies (tuple of str): Bodies that are objects on the table, not furniture.
        exclude_geom_prefix (str): Geoms whose names start with this are object slots, not furniture.
        robot_root (str): The robot's root body (everything under it is the robot).

    Returns:
        list of tuple: (geom type, centre (3,), rotation (3, 3), size (3,)) of boxes, cylinders, capsules and spheres (the floor plane is left out).

    Raises:
        NotImplementedError: For a furniture geom of another type.
    """
    root = model.body(robot_root).id

    def under_root(b):
        while b > 0:
            if b == root:
                return True
            b = int(model.body_parentid[b])
        return False

    out = []
    for g in range(model.ngeom):
        if not (model.geom_contype[g] or model.geom_conaffinity[g]):
            continue
        b = int(model.geom_bodyid[g])
        if under_root(b) or model.body(b).name in exclude_bodies or (model.geom(g).name or "").startswith(exclude_geom_prefix):
            continue
        t = int(model.geom_type[g])
        if t == T.mjGEOM_PLANE:
            continue
        if t not in (T.mjGEOM_BOX, T.mjGEOM_CYLINDER, T.mjGEOM_CAPSULE, T.mjGEOM_SPHERE):
            raise NotImplementedError(f"furniture geom type {t}")
        out.append((t, data.geom_xpos[g].copy(), data.geom_xmat[g].reshape(3, 3).copy(), model.geom_size[g].copy()))
    return out


def _sdf_primitive(p, t, c, R, s):
    """Signed distance (negative inside) of points p (..., 3) to one primitive."""
    l = (p - c) @ R                                                    # the points in the primitive's frame (R^T applied to row vectors)
    if t == T.mjGEOM_BOX:
        q = np.abs(l) - s
        return np.linalg.norm(np.maximum(q, 0.0), axis=-1) + np.minimum(q.max(axis=-1), 0.0)
    if t == T.mjGEOM_CYLINDER:
        dr, dz = np.hypot(l[..., 0], l[..., 1]) - s[0], np.abs(l[..., 2]) - s[1]
        return np.hypot(np.maximum(dr, 0.0), np.maximum(dz, 0.0)) + np.minimum(np.maximum(dr, dz), 0.0)
    if t == T.mjGEOM_CAPSULE:
        z = l[..., 2] - np.clip(l[..., 2], -s[1], s[1])
        return np.sqrt(l[..., 0] ** 2 + l[..., 1] ** 2 + z ** 2) - s[0]
    return np.linalg.norm(l, axis=-1) - s[0]                             # sphere


class SdfGrid:
    """The signed distance field of a list of primitives on a voxel grid, with trilinear lookup.

    Attributes:
        origin (numpy.ndarray): World position of voxel (0, 0, 0), metres.
        voxel (float): Voxel edge, metres.
        field (numpy.ndarray): float32 (nx, ny, nz) signed distance, clipped to [-look, look].
    """

    def __init__(self, prims, lo, hi, voxel=0.02, look=0.5, chunk=400_000):
        self.origin, self.voxel, self.look = np.asarray(lo, float), float(voxel), float(look)
        n = np.ceil((np.asarray(hi, float) - self.origin) / self.voxel).astype(int) + 1
        xs = [self.origin[i] + np.arange(n[i]) * self.voxel for i in range(3)]
        G = np.stack(np.meshgrid(*xs, indexing="ij"), axis=-1).reshape(-1, 3)
        field = np.full(len(G), self.look, np.float32)
        near = [pr for pr in prims if self._near(pr, lo, hi)]
        for a in range(0, len(G), chunk):
            P = G[a:a + chunk]
            d = np.full(len(P), self.look)
            for t, c, R, s in near:
                d = np.minimum(d, _sdf_primitive(P, t, c, R, s))
            field[a:a + chunk] = np.clip(d, -self.look, self.look)
        self.field = field.reshape(tuple(n))

    @staticmethod
    def _near(pr, lo, hi, margin=0.6):
        t, c, R, s = pr
        r = float(np.linalg.norm(s)) + margin
        return bool(np.all(c + r >= lo) and np.all(c - r <= hi))

    def lookup(self, P):
        """Signed distance at world points P (..., 3), trilinear; outside the grid the nearest voxel's value."""
        idx = ((np.asarray(P, float) - self.origin) / self.voxel).reshape(-1, 3).T
        return ndimage.map_coordinates(self.field, idx, order=1, mode="nearest").reshape(np.shape(P)[:-1])


def surface_samples(model, data, g, spacing=0.015):
    """Points on the surface of one geom in the world frame, about `spacing` apart (boxes: face grids; cylinders and capsules: rings; spheres; meshes: the triangles).

    Args:
        model (mujoco.MjModel): The compiled model.
        data (mujoco.MjData): Its data after a kinematics pass.
        g (int): The geom id.
        spacing (float): The sample spacing, metres. Defaults to 0.015.

    Returns:
        numpy.ndarray: (N, 3) world points.
    """
    t, s = int(model.geom_type[g]), model.geom_size[g]
    R, p = data.geom_xmat[g].reshape(3, 3), data.geom_xpos[g]
    if t == T.mjGEOM_BOX:
        pts = []
        for ax in range(3):
            o = [i for i in range(3) if i != ax]
            u = np.linspace(-s[o[0]], s[o[0]], max(2, int(2 * s[o[0]] / spacing) + 1))
            v = np.linspace(-s[o[1]], s[o[1]], max(2, int(2 * s[o[1]] / spacing) + 1))
            U, V = np.meshgrid(u, v)
            for sg in (-1, 1):
                F = np.zeros((U.size, 3))
                F[:, o[0]], F[:, o[1]], F[:, ax] = U.ravel(), V.ravel(), sg * s[ax]
                pts.append(F)
        L = np.concatenate(pts)
    elif t == T.mjGEOM_MESH:
        mid = int(model.geom_dataid[g])
        vadr, vn = int(model.mesh_vertadr[mid]), int(model.mesh_vertnum[mid])
        V = model.mesh_vert[vadr:vadr + vn].astype(float)
        fadr, fn = int(model.mesh_faceadr[mid]), int(model.mesh_facenum[mid])
        Fc = model.mesh_face[fadr:fadr + fn]
        A, B, C = V[Fc[:, 0]], V[Fc[:, 1]], V[Fc[:, 2]]
        area = 0.5 * np.linalg.norm(np.cross(B - A, C - A), axis=1)
        k = np.maximum(1, np.ceil(area / (spacing ** 2)).astype(int))
        rng = np.random.default_rng(0)
        pts = [V]
        for i in np.nonzero(k > 1)[0]:
            r = rng.random((int(k[i]), 2))
            flip = r.sum(axis=1) > 1
            r[flip] = 1 - r[flip]
            pts.append(A[i] + r[:, :1] * (B[i] - A[i]) + r[:, 1:] * (C[i] - A[i]))
        L = np.concatenate(pts)
    elif t in (T.mjGEOM_CYLINDER, T.mjGEOM_CAPSULE):
        nring = max(8, int(2 * math.pi * s[0] / spacing))
        ang = np.linspace(0, 2 * math.pi, nring, endpoint=False)
        ring = np.c_[s[0] * np.cos(ang), s[0] * np.sin(ang)]
        zs = np.linspace(-s[1], s[1], max(2, int(2 * s[1] / spacing) + 1))
        L = np.concatenate([np.c_[ring, np.full(len(ring), z)] for z in zs])
        if t == T.mjGEOM_CYLINDER:
            for z in (-s[1], s[1]):
                for r in np.arange(spacing, s[0], spacing):
                    L = np.concatenate([L, np.c_[r * np.cos(ang[::2]), r * np.sin(ang[::2]), np.full(len(ang[::2]), z)]])
        else:
            for dz in (-s[1], s[1]):
                for a in np.linspace(-math.pi / 2, math.pi / 2, 7)[1:-1] * (1 if dz > 0 else -1):
                    L = np.concatenate([L, np.c_[s[0] * math.cos(a) * np.cos(ang), s[0] * math.cos(a) * np.sin(ang), np.full(len(ang), dz + s[0] * math.sin(a))]])
    elif t == T.mjGEOM_SPHERE:
        a = np.linspace(-math.pi / 2, math.pi / 2, 9)
        ang = np.linspace(0, 2 * math.pi, 16, endpoint=False)
        L = np.concatenate([np.c_[s[0] * math.cos(x) * np.cos(ang), s[0] * math.cos(x) * np.sin(ang), np.full(len(ang), s[0] * math.sin(x))] for x in a])
    else:
        raise NotImplementedError(f"geom type {t}")
    return L @ R.T + p


def _decimate(P, cell):
    """Keeps one point per cubic cell of edge `cell`."""
    key = np.floor(P / cell).astype(np.int64)
    _, first = np.unique(key, axis=0, return_index=True)
    return P[np.sort(first)]


class HomeClearanceMap:
    """The arms-at-home clearance to the furniture, for any stance, by lookup (see the module docstring).

    Attributes:
        points (numpy.ndarray): (M, 3) surface points of both arms at the zombie pose, in the frame of a base at the origin with yaw 0 and pedestal command 0 (z is the world height).
        grid (SdfGrid): The furniture's distance field.
    """

    def __init__(self, model, data, chk, window_centre, window_half=1.3, cfg=STANCE_CFG, requirements=STANCE_REQUIREMENTS, robot_geometry=None, voxel=0.02,
                 coarse_cell=0.05, max_points=600, sample_margin=0.003, slack=0.01):
        """Builds the distance field and takes the arms' surface samples.

        Args:
            model (mujoco.MjModel): The compiled model (the scene, with the robot).
            data (mujoco.MjData): Its data (the objects placed).
            chk (src.stance_checks.StanceChecks): A StanceChecks of this model: it places the robot at a stance with both arms at home and lists the arm geoms.
            window_centre (array-like): The centre (x, y) of the floor window the quick search uses, metres.
            window_half (float): The window's half width, metres. Defaults to 1.3 (STANCE_CFG["window"]).
            cfg (dict): STANCE_CFG, for the heading robustness. Defaults to it.
            requirements (dict): STANCE_REQUIREMENTS ("home_min_clearance"). Defaults to it.
            robot_geometry (dict or None): From stance_finder.robot_geometry ("lift_factor"). Defaults to None: 1.0, the one slide joint.
            voxel (float): The distance field's voxel, metres. Defaults to 0.02.
            coarse_cell (float): The floor cell of the clearance computation; the mask is interpolated from it to the quick search's cells, metres. Defaults to 0.05.
            max_points (int): The most arm surface points used (they are thinned to a coarser cell until fewer). Defaults to 600.
            sample_margin (float): Subtracted from the clearance for the gaps between surface samples, metres. Defaults to 0.003.
            slack (float): A cell counts as clear down to home_min_clearance - slack (the full check decides exactly), metres. Defaults to 0.01.
        """
        self.cfg, self.min_clear, self.slack, self.sample_margin = cfg, float(requirements["home_min_clearance"]), float(slack), float(sample_margin)
        self._model, self._chk, self._held = model, chk, {}
        self.lift = 1.0 if robot_geometry is None else float(robot_geometry["lift_factor"])
        self.coarse = float(coarse_cell)
        self.centre = np.asarray(window_centre, float)
        self.half = float(window_half)
        chk.place((0.0, 0.0, 0.0, 0.0))
        d = chk.d
        pts = np.concatenate([surface_samples(model, d, g) for g in chk.arm_geoms])
        cell = 0.01
        P = _decimate(pts, cell)
        while len(P) > max_points:
            cell *= 1.25
            P = _decimate(pts, cell)
        self.points = P
        prims = furniture_primitives(model, data)
        reach = 1.1                                                        # the arms at home stay within this of the base origin
        lo = np.array([self.centre[0] - self.half - reach, self.centre[1] - self.half - reach, 0.0])
        hi = np.array([self.centre[0] + self.half + reach, self.centre[1] + self.half + reach, float(P[:, 2].max() + 0.3 + 0.1)])
        self.grid = SdfGrid(prims, lo, hi, voxel=voxel)
        self.n_primitives = len(prims)

    def held_points(self, radius, height, frac, spacing=0.015):
        """J2: surface samples of the held beaker's cylinder with the arms at home, in the same frame as `points` (a base at the origin, yaw 0, pedestal command 0).

        The cylinder stands with its axis vertical through the left pad centre (the grasp is at the beaker's axis), the pad centre `frac` of the height above its bottom; the gripper is closed (an object is held).
        """
        key = (round(float(radius), 4), round(float(height), 4), round(float(frac), 4))
        if key not in self._held:
            from src.gripper_geometry import gripper_frame
            m, chk = self._model, self._chk
            chk.place((0.0, 0.0, 0.0, 0.0))
            d = chk.d
            pad = d.xpos[m.body("openarm_left_hand_tcp").id] + d.xmat[m.body("openarm_left_hand_tcp").id].reshape(3, 3) @ np.asarray(gripper_frame(m, "left")["pad_center_in_tcp"], float)
            z0 = pad[2] - frac * height
            pts = []
            for z in np.arange(z0, z0 + height + 1e-9, spacing):
                for a in np.arange(0.0, 2 * math.pi, spacing / radius):
                    pts.append([pad[0] + radius * math.cos(a), pad[1] + radius * math.sin(a), z])
            for rr in np.arange(spacing, radius, spacing):                 # the two end caps
                for a in np.arange(0.0, 2 * math.pi, spacing / rr):
                    for z in (z0, z0 + height):
                        pts.append([pad[0] + rr * math.cos(a), pad[1] + rr * math.sin(a), z])
            self._held[key] = np.asarray(pts, float)
        return self._held[key]

    def held_clear_mask(self, heading, qs, X, Y, radius, height, frac, back_m=None, step=0.05):
        """J2: the clear mask of clear_mask with the held beaker counted, as a base drives in holding it: the arms and the beaker at the stance, and the beaker alone along the creep-in path.

        Args:
            heading, qs, X, Y: As clear_mask.
            radius (float): The beaker's radius, metres.
            height (float): Its height, metres.
            frac (float): The pad centre's height as a fraction of the beaker's height.
            back_m (float or None): The creep-in distance; the base is at the stance `s` metres back along its heading for s in 0 .. back_m (every `step`); None: the stance only.
            step (float): The spacing of the path samples, metres. Defaults to 0.05.

        Returns:
            numpy.ndarray: Bool (nq, ny, nx): True where the clearance is at least home_min_clearance - slack everywhere.
        """
        hp = self.held_points(radius, height, frac)
        both = np.concatenate([self.points, hp])
        ok = self.clear_mask(heading, qs, X, Y, points=both)
        if back_m:
            c, s_ = math.cos(heading), math.sin(heading)
            for s in np.arange(step, back_m + 1e-9, step):
                ok &= self.clear_mask(heading, qs, X - c * s, Y - s_ * s, points=hp)
        return ok

    def clearance(self, theta, q, x, y, points=None):
        """The smallest distance of the arms at home to the furniture, metres (at most the field's look distance), for base positions x, y (arrays of any shape) at heading theta and pedestal command q."""
        x, y = np.asarray(x, float), np.asarray(y, float)
        c, s = math.cos(theta), math.sin(theta)
        pts = self.points if points is None else points
        px, py, pz = pts[:, 0], pts[:, 1], pts[:, 2] + self.lift * q
        out = np.empty(x.size)
        xf, yf = x.ravel(), y.ravel()
        step = max(1, 4_000_000 // max(len(px), 1))
        for a in range(0, xf.size, step):
            xs, ys = xf[a:a + step, None], yf[a:a + step, None]
            W = np.stack([xs + c * px - s * py, ys + s * px + c * py, np.broadcast_to(pz, (xs.shape[0], len(px)))], axis=-1)
            out[a:a + step] = self.grid.lookup(W).min(axis=1)
        return out.reshape(x.shape) - self.sample_margin

    def clear_mask(self, heading, qs, X, Y, points=None):
        """Which cells are clear of the furniture with the arms at home, for the quick search: (nq, ny, nx) bool, with the heading robustness of the quick search (the heading +-delta too).

        Args:
            heading (float): The heading, radians.
            qs (iterable of float): The pedestal commands.
            X (numpy.ndarray): The quick search's cell centre x coordinates (ny, nx), metres.
            Y (numpy.ndarray): Their y coordinates (ny, nx).
            points (numpy.ndarray or None): Surface points (M, 3) in the frame of `points` to use instead of the arms' (J2: the arms and the held beaker, or the beaker alone). Defaults to the arms'.

        Returns:
            numpy.ndarray: Bool (nq, ny, nx): True where the clearance is at least home_min_clearance - slack at the heading and at heading +-heading_robust_deg.
        """
        x0, x1, y0, y1 = float(X.min()), float(X.max()), float(Y.min()), float(Y.max())
        nxc, nyc = max(2, int(math.ceil((x1 - x0) / self.coarse)) + 1), max(2, int(math.ceil((y1 - y0) / self.coarse)) + 1)
        xc, yc = np.linspace(x0, x1, nxc), np.linspace(y0, y1, nyc)
        XC, YC = np.meshgrid(xc, yc)
        delta = math.radians(self.cfg["heading_robust_deg"])
        thetas = [heading] if delta == 0 else [heading - delta, heading, heading + delta]
        ix = (X - x0) / max(x1 - x0, 1e-9) * (nxc - 1)
        iy = (Y - y0) / max(y1 - y0, 1e-9) * (nyc - 1)
        out = np.zeros((len(qs), *X.shape), bool)
        for qi, q in enumerate(qs):
            worst = np.minimum.reduce([self.clearance(th, float(q), XC, YC, points) for th in thetas])
            fine = ndimage.map_coordinates(worst, np.stack([iy.ravel(), ix.ravel()]), order=1, mode="nearest").reshape(X.shape)
            out[qi] = fine >= self.min_clear - self.slack
        return out
